// Stand-in for the database
const users = [
  { email: "a@example.com", password: "secret123" }
];

// The 'application' logic the server runs for a login request
function handleLogin(email, password) {
  const user = users.find(u => u.email === email); // look up by email
  if (user && user.password === password) {
    return { status: 200, page: "home.html" };     // match: send the home page
  }
  return { status: 401, page: "login.html", error: "Wrong email or password" };
}

console.log(handleLogin("a@example.com", "secret123")); // home.html
console.log(handleLogin("a@example.com", "nope"));      // login.html with error
